// The stop button of the calibration animations ran in a background thread: showButton(text, 60) waited for a
// click or 60 seconds while the animation played, then saved the seconds waited, cleared jeuxdemain.stopButton
// to end the animation, and showed the result image. A permanent button and a 60-second timer do the same.
let jeuxPauseStart = getTimestamp()
function jeuxPauseStop(key, seconds, image) {
  if load("jeuxdemain.stopButton") == true {
    save seconds as key
    save false as "jeuxdemain.stopButton"
    showImage image
  }
}

